import {fitLines} from './svg-text.js?v=astral-3';
import {titleCase} from './title-case.js';
export function makeSourceOverview(svg,payload,t,onSelect){
 const doc=new DOMParser().parseFromString(payload.high,'text/html'),sourceSvg=doc.querySelector('svg'),ns='http://www.w3.org/2000/svg';
 const el=(tag,attrs={},copy)=>{const n=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(copy!==undefined)n.textContent=copy;return n;};
 const text=(x,y,copy,cls='flow-meta')=>el('text',{x,y,class:cls},copy);
 const frames=payload.data.frames,records={},positions={};let width,height;
 function record(f,P,id,title,index){const a=t.activities.filter(a=>P?a.processId===P.id:a.stageId===f.id);const pain=[...new Set(a.flatMap(a=>a.pp||[]).concat(f.stagePain||f.pp||[],(f.ch||[]).map(c=>c.full||c.t)))];return{id,t:title,f,P,index,st:frames.indexOf(f)+1,count:a.length,man:a.filter(x=>(x.effectiveType||x.ty)==='man').length,hyb:a.filter(x=>(x.effectiveType||x.ty)==='hyb').length,auto:a.filter(x=>(x.effectiveType||x.ty)==='auto').length,pain,inp:f.up.map(x=>x.p+': '+x.w),out:f.down.map(x=>x.p+': '+x.w)};}
 function wire(g,r){records[r.id]=r;g.classList.add('flow-node');g.dataset.process=r.id;g.dataset.stage=r.st;g.setAttribute('role','button');g.setAttribute('tabindex',0);g.setAttribute('aria-haspopup','dialog');g.setAttribute('aria-label',`${r.t}, ${r.count} Activities. Open Information Card.`);g.removeAttribute('onclick');g.onclick=()=>onSelect(r,g);g.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();onSelect(r,g);}};}
 function lines(value,len,max=5){const out=[];let line='';String(value).split(/\s+/).forEach(w=>{if((line+' '+w).trim().length>len&&line){out.push(line);line=w;}else line=(line+' '+w).trim();});if(line)out.push(line);if(out.length>max){out.length=max;out[max-1]+='…';}return out;}
 if(sourceSvg){
  const box=sourceSvg.getAttribute('viewBox').split(/\s+/).map(Number);width=box[2];height=box[3];svg.innerHTML=sourceSvg.innerHTML;svg.setAttribute('viewBox',box.join(' '));
  svg.querySelectorAll('[onclick]').forEach(n=>n.removeAttribute('onclick'));
  svg.querySelectorAll('rect').forEach(r=>{const originalFill=r.getAttribute('fill'),w=+r.getAttribute('width'),h=+r.getAttribute('height');if(w>900&&h>100){r.remove();return;}if(h<=10&&/var\(--(man|hyb|auto)\)/.test(r.getAttribute('fill')||''))return;r.setAttribute('fill','#3d2d45');r.setAttribute('fill-opacity','1');r.setAttribute('stroke','#a9809f');r.setAttribute('stroke-width','.8');if(h<25){r.setAttribute('rx','4');r.setAttribute('fill','var(--base)');}if(originalFill==='#e6f4ec'){r.setAttribute('fill','#26332f');r.setAttribute('stroke','#6c9c8d');}if(w<=6&&h>40)r.remove();});
  svg.querySelectorAll('path').forEach(p=>{if(p.closest('defs')){p.setAttribute('fill','#c6adce');return;}p.setAttribute('stroke','#c6adce');p.setAttribute('stroke-width','1.1');if(p.getAttribute('marker-end')){const signal=p.cloneNode();signal.removeAttribute('marker-end');signal.classList.add('flow-signal');p.after(signal);}});
  svg.querySelectorAll('text').forEach(n=>{n.setAttribute('fill','var(--muted)');n.setAttribute('font-weight','400');if(!n.closest('.hln')&&/^\s*(PLANNING CYCLE|MONTHLY CYCLE|WEEKLY CYCLE)/.test(n.textContent)){n.textContent=titleCase(n.textContent.toLowerCase());n.setAttribute('font-weight','600');n.setAttribute('fill','var(--accent)');}});
  svg.querySelectorAll('circle').forEach(n=>n.setAttribute('fill','var(--accent)'));
  svg.querySelectorAll('.hln').forEach((g,i)=>{const id=g.dataset.p;let f=frames.find(f=>f.procs.some(P=>P.id===id));if(!f)return;const P=f.procs.find(P=>P.id===id),title=titleCase(P.name),r=record(f,P,id,title,i+1);wire(g,r);g.querySelector('rect')?.classList.add('flow-node-body');g.querySelectorAll('text').forEach(n=>{if(+n.getAttribute('font-size')>=15){n.setAttribute('y',Number(n.getAttribute('y'))+3);n.setAttribute('fill','var(--ink)');n.setAttribute('font-weight','600');n.textContent=titleCase(n.textContent);}if(n.getAttribute('text-anchor')==='middle')n.setAttribute('fill','var(--accent-ink)');});});
 }else{
  const cells=[...doc.querySelectorAll('.hlc')],W=320,H=196,gapX=80,gapY=100;
  const cols=Math.max(...cells.map(c=>parseInt(c.style.gridColumn)||1));const rows=Math.max(...cells.map(c=>parseInt(c.style.gridRow)||1));width=cols*(W+gapX)+48;height=rows*(H+gapY)+100;
  svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const defs=el('defs'),marker=el('marker',{id:'source-high-arrow',viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:7,markerHeight:7,orient:'auto'});marker.append(el('path',{d:'M0 0 L10 5 L0 10 Z',fill:'#c6adce'}));defs.append(marker);svg.append(defs);
  const subtitle=doc.querySelector('.hlbar small')?.textContent||'';svg.append(text(48,34,subtitle.split('· click')[0],'flow-cycle-period'));
  cells.forEach(c=>{const col=parseInt(c.style.gridColumn)||1,row=parseInt(c.style.gridRow)||1,x=48+(col-1)*(W+gapX),y=80+(row-1)*(H+gapY);c.dataset.x=x;c.dataset.y=y;
   const next=c.classList.contains('r')?cells.find(n=>parseInt(n.style.gridColumn)===col+1&&parseInt(n.style.gridRow)===row):c.classList.contains('l')?cells.find(n=>parseInt(n.style.gridColumn)===col-1&&parseInt(n.style.gridRow)===row):c.classList.contains('d')?cells.find(n=>parseInt(n.style.gridColumn)===col&&parseInt(n.style.gridRow)===row+1):null;
   if(next){const direction=c.classList.contains('r')?'r':c.classList.contains('l')?'l':'d';const d=direction==='r'?`M${x+W},${y+H/2} h${gapX}`:direction==='l'?`M${x},${y+H/2} h${-gapX}`:`M${x+W/2},${y+H} v${gapY}`;svg.append(el('path',{d,class:'overview-edge main','marker-end':'url(#source-high-arrow)'}),el('path',{d,class:'flow-signal'}));}
  });
  cells.forEach(c=>{const x=+c.dataset.x,y=+c.dataset.y,b=c.querySelector('.hlb'),index=Number(b.querySelector('.bd')?.textContent),f=frames[index-1],title=titleCase(b.querySelector('h4')?.textContent||'Source Handoff'),g=el('g');g.append(el('title',{},b.textContent),el('rect',{x,y,width:W,height:H,rx:8,class:'flow-node-body'}));
   if(f){const r=record(f,null,f.id,title,index);wire(g,r);g.append(text(x+18,y+27,String(index).padStart(2,'0'),'flow-index'));const stage=text(x+W-18,y+27,`Stage ${index}`,'flow-stage');stage.setAttribute('text-anchor','end');g.append(stage);const ls=fitLines(title,W-36,18,4,600);ls.forEach((l,i)=>g.append(text(x+18,y+57+i*23,l,'flow-title')));g.append(text(x+18,y+153,`${r.count} Activities · ${r.pain.length} Pain Point${r.pain.length===1?'':'s'}`));let bx=x+18;['man','hyb','auto'].forEach(ty=>{const w=100*r[ty]/Math.max(r.count,1);if(w)g.append(el('rect',{x:bx,y:y+174,width:w,height:4,fill:`var(--${ty})`}));bx+=w;});g.append(text(x+W-147,y+180,`${r.man} M · ${r.hyb} S · ${r.auto} A`,'flow-mix'));
   }else{g.append(text(x+18,y+36,title,'flow-title'));fitLines(b.querySelector('p')?.textContent||'',W-36,11.5,7).forEach((l,i)=>g.append(text(x+18,y+65+i*18,l)));}svg.append(g);
  });
 }
 return{width,height,records,positions,setScale(scale){svg.style.width=width*scale+'px';svg.style.height=height*scale+'px';},setFilter(filter){svg.querySelectorAll('.flow-node').forEach(g=>{const r=records[g.dataset.process];g.classList.toggle('unfocused',!(filter==='all'||filter==='pp'&&r.pain.length||r[filter]));});},markStage(stage){svg.querySelectorAll('.flow-node').forEach(g=>g.classList.toggle('stage-current',+g.dataset.stage===stage+1));}};
}
